314		For $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
315		\begin{equation}\label{eq:qld-sg-cons}
316			\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_P^{\mathrm{id}}} \Id
